<?php /** One editable line (or the blank add row when l is null). Data: l, doc, prefix, pdo, items, taxRates, departments, sites, currency, side, kind */
$exp = ($side ?? 'income') === 'expense'; $lid = $l === null ? 'new' : (int) $l[$kind . '_line_id']; $p = $prefix; $f = $p . '-line-form-' . $lid; $rid = $p . '-line-' . $lid; ?>
<tr id="<?= e($rid) ?>" class="<?= $l === null ? 'table-light' : '' ?>">
    <td class="text-muted fs-12 align-middle"><?= $l === null ? '+' : (int) $l['sort_order'] ?></td>
    <td><select form="<?= e($f) ?>" name="item" class="form-select form-select-sm" id="<?= e($rid) ?>-item"><option value="">—</option><?php foreach ($items as $it): ?><option value="<?= $it['item_id'] ?>" <?= ($l['item_id'] ?? null) === $it['item_id'] ? 'selected' : '' ?>><?= e($it['name']) ?></option><?php endforeach; ?></select></td>
    <td><input form="<?= e($f) ?>" type="text" name="description" class="form-control form-control-sm" maxlength="300" value="<?= e($l['description'] ?? '') ?>" id="<?= e($rid) ?>-description"></td>
    <td><input form="<?= e($f) ?>" type="text" inputmode="decimal" name="quantity" class="form-control form-control-sm text-end" value="<?= e($l === null ? '1' : rtrim(rtrim((string) $l['quantity'], '0'), '.')) ?>" id="<?= e($rid) ?>-quantity"></td>
    <td><input form="<?= e($f) ?>" type="text" inputmode="decimal" name="unit_price" class="form-control form-control-sm text-end" value="<?= e($l['unit_price'] ?? '') ?>" id="<?= e($rid) ?>-price"></td>
    <td><select form="<?= e($f) ?>" name="tax_rate" class="form-select form-select-sm" id="<?= e($rid) ?>-tax"><option value="">None</option><?php foreach ($taxRates as $t): ?><option value="<?= (int) $t['tax_rate_id'] ?>" <?= ($l['tax_rate_id'] ?? null) === (int) $t['tax_rate_id'] ? 'selected' : '' ?>><?= e($t['name']) ?></option><?php endforeach; ?></select></td>
    <td><?= $exp ? account_select($pdo, 'expense_account', $l['expense_account_id'] ?? null, ['expense', 'asset'], [], 'form="' . e($f) . '"', $l === null ? 'Default' : null, $rid . '-account') : account_select($pdo, 'income_account', $l['income_account_id'] ?? null, ['income'], [], 'form="' . e($f) . '"', $l === null ? 'Default' : null, $rid . '-account') ?></td>
    <td><select form="<?= e($f) ?>" name="department" class="form-select form-select-sm" id="<?= e($rid) ?>-department"><option value="">—</option><?php foreach ($departments as $d): ?><option value="<?= (int) $d['department_id'] ?>" <?= ($l['department_id'] ?? null) === (int) $d['department_id'] ? 'selected' : '' ?>><?= e($d['name']) ?></option><?php endforeach; ?></select></td>
    <td><select form="<?= e($f) ?>" name="site" class="form-select form-select-sm" id="<?= e($rid) ?>-site"><option value="">—</option><?php foreach ($sites as $s): ?><option value="<?= (int) $s['site_id'] ?>" <?= ($l['site_id'] ?? null) === (int) $s['site_id'] ? 'selected' : '' ?>><?= e($s['name']) ?></option><?php endforeach; ?></select></td>
    <td class="text-end align-middle text-nowrap" id="<?= e($rid) ?>-total"><?= $l === null ? '' : e(fmt_money($l['line_total'], $currency, false)) ?></td>
    <td class="text-nowrap"><button form="<?= e($f) ?>" type="submit" class="btn btn-sm btn-primary" id="<?= e($rid) ?>-save-btn"><?= $l === null ? 'Add' : 'Save' ?></button><?php if ($l !== null): ?> <button form="<?= e($p . '-line-remove-' . $lid) ?>" type="submit" class="btn btn-sm btn-light text-danger" id="<?= e($rid) ?>-remove-btn" title="Remove">&times;</button><?php endif; ?></td>
</tr>
